action_yml_list:
[{'name': 'Setup scoop', 'description': 'Setup scoop and update PATH for GitHub Actions workflow on Windows environment.', 'inputs': {'install_scoop': {'description': 'Install scoop if true (default)', 'required': True, 'default': 'true'}, 'add_extras_bucket': {'description': 'Add extras bucket if true (default)', 'required': True, 'default': 'false'}, 'add_nonportable_bucket': {'description': 'Add nonportable bucket if true (default)', 'required': True, 'default': 'false'}, 'scoop_update': {'description': 'Call scoop update if true (default)', 'required': True, 'default': 'true'}, 'scoop_checkup': {'description': 'Call scoop checkup if true (default)', 'required': True, 'default': 'false'}, 'update_path': {'description': 'Update environment variable PATH for workflow if true (default)', 'required': True, 'default': 'true'}}, 'runs': {'using': 'composite', 'steps': [{'name': 'Setup scoop', 'shell': 'pwsh', 'run': 'if('${{ inputs.install_scoop }}' -eq 'true') {Invoke-Expression "& { $(Invoke-RestMethod https://get.scoop.sh) } -RunAsAdmin"}
if('${{ inputs.update_path }}' -eq 'true') {Join-Path (Resolve-Path ~).Path "scoop\shims" >> $Env:GITHUB_PATH}
if('${{ inputs.add_extras_bucket }}' -eq 'true') {scoop bucket add extras}
if('${{ inputs.add_nonportable_bucket }}' -eq 'true') {scoop bucket add nonportable}
if('${{ inputs.scoop_update }}' -eq 'true') {scoop update}
if('${{ inputs.scoop_checkup }}' -eq 'true') {scoop checkup}
'}]}}]

action_file_descriptions:
['Setup Godot for headless use with macOS, Windows, and Linux CI/CD runners.', 'Godot 4 version: e.g., 4.0.0-beta1, 4.0.0-beta.16, 4.0.0, etc. Must include major, minor, and patch (additional pre-release label is optional). Specify `global` or `global.json` to use the version from the project's global.json file.
```yaml - uses: chickensoft/setup-godot-action@v1
  with:
    version: global
```
In the root of your project, include a global.json file:
```json {
  "sdk": {
    "version": "6.0.406",
    "rollForward": "latestMinor"
  },
  "msbuild-sdks": {
    "Godot.NET.Sdk": "4.0.0"
  }
} ```
**Important:** If using a global.json file in your project, do *not* specify the version of the Godot.NET.Sdk in your project's `*.csproj` file.
```xml <Project Sdk="Godot.NET.Sdk"> <!-- GOOD --> <Project Sdk="Godot.NET.Sdk/4.0.0"> <!-- BAD --> ```', 'Path to install Godot to, relative to the current working directory of the action.', 'Path to download Godot to, relative to the current working directory of the action.', 'Path for binaries to be installed to, relative to the current working directory of the action. This is the path that will be added to the system path.', 'Whether to use the release or debug version of GodotSharp.dll. The appropriate version will be symlinked in bin-path.', 'True to use the .NET-enabled version of Godot that enables C#, false to use the default version.', 'True will also download the Godot Export Templates for each platform.', 'True to cache downloads.']

