```json {
  "sdk": {
    "version": "6.0.406",
    "rollForward": "latestMinor"
  },
  "msbuild-sdks": {
    "Godot.NET.Sdk": "4.0.0"
  }
} ```
**Important:** If using a global.json file in your project, do *not* specify the version of the Godot.NET.Sdk in your project's `*.csproj` file.
```xml <Project Sdk="Godot.NET.Sdk"> <!-- GOOD --> <Project Sdk="Godot.NET.Sdk/4.0.0"> <!-- BAD --> ```', 'required': True}, 'path': {'description': 'Path to install Godot to, relative to the current working directory of the action.', 'default': 'godot'}, 'downloads-path': {'description': 'Path to download Godot to, relative to the current working directory of the action.', 'default': 'downloads'}, 'bin-path': {'description': 'Path for binaries to be installed to, relative to the current working directory of the action. This is the path that will be added to the system path.', 'default': 'bin'}, 'godot-sharp-release': {'description': 'Whether to use the release or debug version of GodotSharp.dll. The appropriate version will be symlinked in bin-path.', 'default': 'false'}, 'use-dotnet': {'description': 'True to use the .NET-enabled version of Godot that enables C#, false to use the default version.', 'default': True}, 'include-templates': {'description': 'True will also download the Godot Export Templates for each platform.', 'default': False}, 'cache': {'description': 'True to cache downloads.', 'default': True}}, 'runs': {'using': 'node24', 'main': 'dist/index.js'}}]

[{'name': 'Docker Buildx Bake', 'description': 'GitHub Action to use Docker Buildx Bake as a high-level build command', 'author': 'docker', 'branding': {'icon': 'anchor', 'color': 'blue'}, 'inputs': {'builder': {'description': 'Builder instance', 'required': False}, 'allow': {'description': 'Allow build to access specified resources (e.g., network.host)', 'required': False}, 'call': {'description': 'Set method for evaluating build (e.g., check)', 'required': False}, 'files': {'description': 'List of bake definition files', 'required': False}, 'no-cache': {'description': 'Do not use cache when building the image', 'required': False, 'default': 'false'}, 'pull': {'description': 'Always attempt to pull a newer version of the image', 'required': False, 'default': 'false'}, 'load': {'description': 'Load is a shorthand for --set=*.output=type=docker', 'required': False, 'default': 'false'}, 'provenance': {'description': 'Provenance is a shorthand for --set=*.attest=type=provenance', 'required': False}, 'push': {'description': 'Push is a shorthand for --set=*.output=type=registry', 'required': False, 'default': 'false'}, 'sbom': {'description': 'SBOM is a shorthand for --set=*.attest=type=sbom', 'required': False}, 'set': {'description': 'List of targets values to override (eg. targetpattern.key=value)', 'required': False}, 'source': {'description': 'Context to build from. Can be either local to specify the working directory or a remote bake definition', 'required': False}, 'targets': {'description': 'List of bake targets', 'required': False}, 'vars': {'description': 'Variables to set in the Bake definition as list of key-value pair', 'required': False}, 'github-token': {'description': 'API token used to authenticate to a Git repository for remote definitions', 'default': '${{ github.token }}', 'required': False}}, 'outputs': {'metadata': {'description': 'Build result metadata'}}, 'runs': {'using': 'node24', 'main': 'dist/index.cjs', 'post': 'dist/index.cjs'}}, {'name': 'Matrix', 'description': 'Generate a matrix from a Bake definition to help distributing builds in your workflow', 'inputs': {'workdir': {'description': 'Working directory', 'default': '.', 'required': False}, 'files': {'description': 'List of Bake files', 'required': False}, 'target': {'description': 'Bake target', 'required': False}, 'fields': {'description': 'List of extra fields to include in the matrix', 'required': False}}, 'outputs': {'matrix': {'description': 'Matrix configuration', 'value': '${{ steps.generate.outputs.includes }}'}}, 'runs': {'using': 'composite', 'steps': [{'name': 'Generate', 'id': 'generate', 'uses': 'actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3', 'env': {'INPUT_WORKDIR': '${{ inputs.workdir }}', 'INPUT_FILES': '${{ inputs.files }}', 'INPUT_TARGET': '${{ inputs.target }}', 'INPUT_FIELDS': '${{ inputs.fields }}'}, 'with': {'script': "function getInputList(name) {
  return core.getInput(name) ? core.getInput(name).split(/[\r?\n,]+/).filter(x => x !== '') : [];
}

const workdir = core.getInput('workdir');
const files = getInputList('files');
const target = core.getInput('target');
const fields = getInputList('fields');

let def = {};
await core.group(`Parsing definition`, async () => {
  let args = ['buildx', 'bake'];
  for (const file of files) {
    args.push('--file', file);
  }
  if (target) {
    args.push(target);
  }
  args.push('--print');
  const res = await exec.getExecOutput('docker', args, {
    ignoreReturnCode: true,
    silent: true,
    cwd: workdir
  });
  if (res.stderr.length > 0 && res.exitCode != 0) {
    throw new Error(res.stderr);
  }
  def = JSON.parse(res.stdout.trim());
  core.info(JSON.stringify(def, null, 2));
});

await core.group(`Generating matrix`, async () => {
  const result = [];
  for (const targetName of Object.keys(def.target)) {
    const target = def.target[targetName];
    const entry = { target: targetName };
    if (fields.length === 0) {
      result.push({ ...entry });
      continue;
    }
    let fieldFound = false;
    Object.keys(target).forEach(field => {
      if (fields.includes(field)) {
        fieldFound = true;
        const value = target[field];
        if (Array.isArray(value)) {
          value.forEach((v) => {
            entry[field] = v;
            result.push({ ...entry });
          });
        } else {
          entry[field] = value;
          result.push({ ...entry });
        }
      }
    });
    if (!fieldFound) {
      result.push({ ...entry });
    }
  }
  core.info(JSON.stringify(result, null, 2));
  core.setOutput('includes', JSON.stringify(result));
});
"}}]}}]

