[{'name': 'Publish', 'description': 'Set the Pages publishing environment and wait for the publication', 'inputs': {'token': {'description': 'The GitHub token', 'required': True}, 'sha': {'description': 'The sha of the commit that is being published', 'required': True}, 'branch': {'description': 'The branch to set as the Pages source', 'required': True}, 'path': {'description': 'The path to set as the Pages source', 'required': True}}, 'runs': {'using': 'composite', 'steps': [{'name': 'Pages Publication', 'uses': 'actions/github-script@v6', 'env': {'SHA': '${{ inputs.sha }}', 'PAGES_BRANCH': '${{ inputs.branch }}', 'PAGES_PATH': '${{ inputs.path }}'}, 'with': {'github-token': '${{ inputs.token }}', 'script': "const {SHA, PAGES_BRANCH, PAGES_PATH} = process.env

await github.rest.repos.updateInformationAboutPagesSite({
  owner: context.repo.owner,
  repo: context.repo.repo,
  source: {
    branch: PAGES_BRANCH,
    path: PAGES_PATH
  }
})

await github.rest.repos.requestPagesBuild({
  owner: context.repo.owner,
  repo: context.repo.repo
})

for (let retry = 1; retry <= 10; retry++) {
  // Starting at 1 so the output message doesn't need manipulation
  const {status, commit} = await github.rest.repos.getLatestPagesBuild({
    owner: context.repo.owner,
    repo: context.repo.repo
  })
  if (commit === SHA) {
    return 
  } else if (retry < 5) {  
    await new Promise(resolve => setTimeout(resolve, 10000))
    core.info(`Site has not been published yet. Retry ${retry}/10`) 
  } else {
    core.info('Site has not been published yet') 
  }
}"}}]}}, {'name': 'Test', 'description': 'Test the published site', 'inputs': {'token': {'description': 'The GitHub token', 'required': True}, 'spec': {'description': 'The scenario to test', 'required': True}, 'suffix': {'description': 'Suffix for the cypress output files name', 'required': True}}, 'runs': {'using': 'composite', 'steps': [{'name': 'Caching', 'uses': 'actions/cache@v3', 'with': {'path': '~/.npm', 'key': "${{ runner.os }}-node-${{ hashFiles('**/package-lock.json') }}", 'restore-keys': '${{ runner.os }}-node
'}}, {'name': 'Get the URL of the rendered site', 'shell': 'sh', 'id': 'rendered-site-url', 'env': {'AUTH_TOKEN': '${{ inputs.token }}'}, 'run': 'full_url=$(curl -sH "Authorization: token ${AUTH_TOKEN}" \
"${GITHUB_API_URL}/repos/${GITHUB_REPOSITORY}/pages" | \
awk -F'"' '/\"html_url\"/ { print $4 }')
url=$(dirname "${full_url}")
echo "url=${url}" >> $GITHUB_OUTPUT
'}, {'name': 'Log the URL of the rendered site', 'shell': 'sh', 'run': 'echo ${{ steps.rendered-site-url.outputs.url }}'}, {'name': 'Cypress run', 'uses': 'cypress-io/github-action@v5.0.5', 'with': {'config': 'baseUrl=${{ steps.rendered-site-url.outputs.url }}', 'working-directory': 'tests/e2e', 'spec': '${{ inputs.spec }}', 'browser': 'chrome'}}, {'name': 'Save Cypress Screenshots', 'uses': 'actions/upload-artifact@v3', 'if': 'failure()', 'with': {'name': 'cypress-screenshots-${{ inputs.suffix  }}', 'path': 'tests/e2e/cypress/screenshots'}}, {'name': 'Save Cypress Videos', 'uses': 'actions/upload-artifact@v3', 'if': 'always()', 'with': {'name': 'cypress-videos-${{ inputs.suffix  }}', 'path': 'tests/e2e/cypress/videos'}}]}}, {'name': 'Jekyll Actions', 'description': 'A GitHub Action to build and publish Jekyll sites to GitHub Pages', 'inputs': {'token': {'description': 'The GITHUB_TOKEN secret', 'required': False}, 'jekyll_env': {'description': 'The Jekyll environment to build', 'required': False}, 'jekyll_src': {'description': 'The Jekyll website source directory', 'required': False}, 'jekyll_build_options': {'description': 'Additional Jekyll build arguments (see https://jekyllrb.com/docs/configuration/options/#build-command-options)', 'required': False}, 'gem_src': {'description': 'The Jekyll Gemfile directory', 'required': False}, 'target_branch': {'description': 'The target branch name the site gets pushed to', 'required': False}, 'target_path': {'description': 'The relative path where the site gets pushed to', 'required': False}, 'build_only': {'description': 'Will build the Jekyll site without publishing it', 'required': False}, 'build_dir': {'description': 'The directory to build your project in', 'required': False}, 'keep_history': {'description': 'Do not overwrite whatever was already published on the target branch', 'required': False}, 'pre_build_commands': {'description': 'Commands to run prior to build and deploy. Useful for ensuring build dependencies are up to date or installing  new dependencies. For example, use `apk --update add  imagemagick` to install ImageMagick.
', 'required': False}, 'bundler_version': {'description': 'When set override the default bundler version provided.', 'required': False}, 'commit_author': {'description': 'Provide an author for commits by the action.  The email address is automatically set to  `[author name]@users.noreply.github.com`
', 'required': False}}, 'outputs': {'sha': {'description': 'Generated commit SHA1 that will be published'}}, 'runs': {'using': 'docker', 'image': 'Dockerfile'}, 'branding': {'icon': 'book', 'color': 'blue'}}]

