[{'name': 'WinGet Releaser', 'description': 'Publish new releases of your application to Windows Package Manager easily.', 'author': 'vedantmgoyal9 (Vedant)', 'inputs': {'identifier': {'required': True, 'description': 'The PackageIdentifier of the package (case-sensitive).'}, 'version': {'required': False, 'description': 'The PackageVersion of the package you want to release.'}, 'installers-regex': {'required': True, 'description': 'The regex to match the installers.', 'default': '.(exe|msi|msix|appx)(bundle){0,1}$'}, 'max-versions-to-keep': {'required': True, 'description': 'The maximum number of versions to keep in WinGet Community Repository (Default: 0 - no limit)', 'default': '0'}, 'release-repository': {'required': True, 'description': 'The repository where the release is present (should be present under same user/organization).', 'default': '${{ github.event.repository.name }}'}, 'release-tag': {'required': True, 'description': 'The release tag to be used for creating manifests.', 'default': '${{ github.event.release.tag_name || github.ref_name }}'}, 'token': {'required': True, 'description': 'GitHub token to create pull request on Windows Package Manager Community Repository.'}, 'fork-user': {'required': True, 'description': 'GitHub username where the fork of winget-pkgs is present.', 'default': '${{ github.repository_owner }}'}}, 'runs': {'using': 'composite', 'steps': [{'run': '# check if at least one version of the package is already present in winget-pkgs repository
$ErrorActionPreference = 'SilentlyContinue'
$PkgId = '${{ inputs.identifier }}'
Invoke-WebRequest -Uri "https://github.com/microsoft/winget-pkgs/tree/master/manifests/$($PkgId.ToLower()[0])\$($PkgId.Replace('.', '/'))" -Method Head
if (-not $?) {
  Write-Output "::error::Package $PkgId does not exist in the winget-pkgs repository. Please add atleast one version of the package before using this action."
  exit 1
}
', 'shell': 'pwsh'}, {'run': '# check if max-versions-to-keep is a valid number and is 0 (keep all versions) or greater than 0
$MaxVersionsToKeep = '${{ inputs.max-versions-to-keep }}'
if (-not [int]::TryParse($MaxVersionsToKeep, [ref]$null) -or $MaxVersionsToKeep -lt 0) {
  Write-Output "::error::Invalid input: max-versions-to-keep should be 0 (zero - keep all versions) or a POSITIVE INTEGER."
  exit 1
}
', 'shell': 'pwsh'}, {'uses': 'cargo-bins/cargo-binstall@main', 'env': {'GITHUB_TOKEN': '${{ github.token }}'}}, {'run': 'cargo binstall komac -y', 'env': {'GITHUB_TOKEN': '${{ github.token }}'}, 'shell': 'pwsh'}, {'run': '# get release information
$ReleaseInfo = Invoke-RestMethod `
  -Uri 'https://api.github.com/repos/${{ github.repository_owner }}/${{ inputs.release-repository }}/releases/tags/${{ inputs.release-tag }}' `
  -Headers @{ Authorization = "token $env:GITHUB_TOKEN" }
If ('' -eq '${{ inputs.version }}') {
  Write-Output "version=$($ReleaseInfo.tag_name -replace '^v')" >> $env:GITHUB_OUTPUT
} Else {
  Write-Output "version=${{ inputs.version }}" >> $env:GITHUB_OUTPUT
